//! Child of existing real Engine/Journal/Git/jj source tests. A local source
//! never becomes a Root SDK owner or an unsupported bounded backing owner.
use super::*;
use fs2::FileExt;
#[test]fn real_current_source_origin_holds_shared_writer_lock_and_refuses_unbounded_local_projection(){let mut f=Fixture::new();let original=budget();let cancelled=Arc::new(AtomicBool::new(false));f.source.prepare(&f.environment,&f.settings,&original,&cancelled).unwrap();let mut out=None;f.source.capture_sdk_build_origin_retaining(&mut out,original.clone(),cancelled).unwrap();let origin=out.as_ref().unwrap();origin.assert_current().unwrap();assert!(origin.runnable_inputs().is_err());
 let lock=f.source.integration.as_ref().unwrap().path.join("rudder-acceptance.lock");let other=OpenOptions::new().read(true).write(true).open(lock).unwrap();assert_eq!(FileExt::try_lock_exclusive(&other).unwrap_err().kind(),std::io::ErrorKind::WouldBlock);assert_eq!(origin.roots_data().unwrap().0,f.source.prepared.as_ref().unwrap().runnable_root);}
#[test]fn cancel_before_source_capture_retains_carrier_and_does_not_revoke_unrelated_owner(){let mut f=Fixture::new();let original=budget();let cancel=Arc::new(AtomicBool::new(false));f.source.prepare(&f.environment,&f.settings,&original,&cancel).unwrap();let lock=f.source.integration.as_ref().unwrap().path.join("rudder-acceptance.lock");let cancelled=budget();cancelled.cancel();let mut out=None;assert!(f.source.capture_sdk_build_origin_retaining(&mut out,cancelled,cancel).is_err());assert!(out.is_some());assert!(!lock.exists());f.engine.assert_current().unwrap();}
#[test]fn real_owner_retirement_or_seed_pin_loss_refuses_the_held_source_origin(){for retire in [false,true]{let mut f=Fixture::new();let original=budget();let cancel=Arc::new(AtomicBool::new(false));f.source.prepare(&f.environment,&f.settings,&original,&cancel).unwrap();let mut out=None;f.source.capture_sdk_build_origin_retaining(&mut out,original.clone(),cancel).unwrap();if retire{f.engine.finish(false).unwrap();}else{let seed=f.source.prepared.as_ref().unwrap().seed_pin.clone();f.source.store.unpin(&seed).unwrap();}assert!(out.as_ref().unwrap().assert_current().is_err());}}
#[test]fn replacement_acceptance_lock_or_accepted_head_cannot_rebind_original_source(){for head in [false,true]{let mut f=Fixture::new();let original=budget();let cancel=Arc::new(AtomicBool::new(false));f.source.prepare(&f.environment,&f.settings,&original,&cancel).unwrap();let mut out=None;f.source.capture_sdk_build_origin_retaining(&mut out,original.clone(),cancel).unwrap();
 if head {let db=rusqlite::Connection::open(f.source.journal.database_path().unwrap()).unwrap();db.execute("UPDATE projects SET integration_head=?1 WHERE project_id=?2",rusqlite::params!["a".repeat(40),f.source.owner().project_id]).unwrap();}
 else{let path=f.source.integration.as_ref().unwrap().path.join("rudder-acceptance.lock");fs::rename(&path,path.with_extension("held-original")).unwrap();OpenOptions::new().write(true).create_new(true).mode(0o600).open(&path).unwrap();}
 assert!(out.as_ref().unwrap().assert_current().is_err());}}
